37	export async function modeSetup(record: SessionRecord, ctx: ModeContext): Promise<ModeSetup> {
38	  const { workspaceRoot } = ctx
39	  // A chat may write a spec when asked to, held to the contract like the planner's.
40	  const chat = { hooks: new SpecContract(workspaceRoot) }
41	  if (record.access === 'full') return chat
42	  switch (record.mode) {
43	    case 'chat':
44	      return chat
45	    case 'implement': {
46	      if (!record.feature) throw new Error('An implement session needs a feature name')
47	      return {
48	        // The user's answers amend the task's rules, held to the contract like the planner's writes.
49	        hooks: composeHooks(new TaskBoardGuard(workspaceRoot, record.feature), new SpecContract(workspaceRoot)),
50	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, implementPrompt(record.feature, workspaceRoot, ctx.verifyRules())))),
51	        toolNames: IMPLEMENT_TOOLS,
52	      }
53	    }
54	    case 'plan': {
55	      if (!record.feature) throw new Error('A plan session needs a feature name')
56	      const scope = blindPlanScope(record.feature, ctx.planIgnore())
57	      return {
58	        // The contract answers on the write that broke it, so the planner fixes the spec in the same turn.
59	        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
60	        systemPrompt: await ctx.withDocs(record, blindPlanPrompt(record.feature, workspaceRoot)),
61	        toolNames: BLIND_PLAN_TOOLS,
62	        readable: readableIn(scope),
63	      }
64	    }
65	    case 'code-plan':
66	      // Read-only by its tool set: nothing to scope, and the build happens once the plan is approved.
67	      return {
68	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, await ctx.withDocs(record, codePlanPrompt(workspaceRoot))))),
69	        toolNames: CODE_PLAN_TOOLS,
70	      }
71	    case 'docs': {
72	      const scope = docsEvaluationScope(ctx.planIgnore())
73	      return {
74	        hooks: new ScopeGuard(workspaceRoot, scope),
75	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withDocs(record, docsEvaluationPrompt(workspaceRoot)))),
76	        toolNames: DOCS_EVALUATION_TOOLS,
77	        readable: readableIn(scope),
78	      }
79	    }
80	    case 'file-decisions': {
81	      const scope = fileDecisionsScope(ctx.planIgnore())
82	      return {
83	        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
84	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withDocs(record, fileDecisionsPrompt(workspaceRoot)))),
85	        toolNames: FILE_DECISIONS_TOOLS,
86	        readable: readableIn(scope),
87	      }
88	    }
89	    case 'docs-map': {
90	      return {
91	        // The entry contract answers on the write that broke it, so a bad anchor never reaches a planner's prompt.
92	        hooks: composeHooks(new ScopeGuard(workspaceRoot, docsMapScope(record.files ?? [])), new DocsMapContract(workspaceRoot)),
93	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, docsMapPrompt(workspaceRoot))),
94	        toolNames: DOCS_MAP_TOOLS,
95	      }
96	    }
97	    case 'reconcile': {
98	      if (!record.feature) throw new Error('A reconcile session needs a feature name')
99	      return {
100	        hooks: composeHooks(
101	          new ScopeGuard(workspaceRoot, reconcileScope(record.feature)),
102	          new SpecContract(workspaceRoot),
103	          new ScenarioContextContract(workspaceRoot, record.feature),
104	        ),
105	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, await ctx.withMap(record, reconcilePrompt(record.feature, workspaceRoot)))),
106	        toolNames: RECONCILE_TOOLS,
107	      }
108	    }
109	    case 'cleanup': {
110	      if (!record.feature || !record.files) throw new Error('A cleanup session needs a feature name and the files to split')
111	      return {
112	        hooks: new ScopeGuard(workspaceRoot, cleanupScope(record.files)),
113	        systemPrompt: await ctx.withInstructions(record, await ctx.withMemories(record, cleanupPrompt(record.feature, workspaceRoot, ctx.cleanupLimits()))),
114	        toolNames: CLEANUP_TOOLS,
115	      }
116	    }
117	  }
118	}
